using System.Text.Json.Nodes;using Koz.Api.Auth;using Koz.Application.Auth;using Koz.Application.Customers;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace Koz.Api.Controllers;
[ApiController,Authorize(Policy=AuthPolicies.Customer)]public sealed class CustomerMutationsController(CustomerMutationService s,ICurrentUser u):ControllerBase{[HttpPut("api/my-profile")]public Task<JsonObject>Profile(JsonObject b,CancellationToken c)=>s.UpdateProfileAsync(u.Id!,b,c);[HttpPost("api/my-addresses")]public async Task<IActionResult>Address(JsonObject b,CancellationToken c)=>StatusCode(201,await s.CreateAddressAsync(u.Id!,b,c));[HttpDelete("api/my-addresses/{id}")]public Task<JsonObject>Delete(string id,CancellationToken c)=>s.DeleteAddressAsync(u.Id!,id,c);}
